{"code": "import random

def simulate_game():
    turn = 'Alice'
    while True:
        if turn == 'Alice':
            # Alice flips
            # Heads (1) -> Alice wins
            # Tails (0) -> Bob's turn
            flip = random.choice([0, 1]) # 1 is Heads, 0 is Tails
            if flip == 1:
                return 1 # Alice wins
            else:
                turn = 'Bob'
        else:
            # Bob flips
            # Tails (0) -> Bob wins
            # Heads (1) -> Alice's turn
            flip = random.choice([0, 1]) # 1 is Heads, 0 is Tails
            if flip == 0:
                return 0 # Bob wins (Alice loses)
            else:
                turn = 'Alice'

num_simulations = 1000000
alice_wins = 0

for _ in range(num_simulations):
    if simulate_game():
        alice_wins += 1

probability = alice_wins / num_simulations
print(f"Simulated probability: {probability}")
print(f"Expected probability: {2/3}")"}
